Set-Location -LiteralPath $PSScriptRoot
$msg = 'compose: the composer knew whether it could TEXT, and only guessed whether it could EMAIL. SMS availability was computed from both halves - the lead has a number, and describe_sms_sender resolves a sender - while email availability was computed from the lead alone and asked nothing at all about the sending address. An organization with no verified From address therefore showed a green, enabled Email button, and the advisor discovered the refusal by pressing Send and reading the error. That asymmetry stopped being cosmetic the moment SMS stopped carrying the booking link: email is now the ONLY channel that carries it, so an email the product believes it can send and cannot is the difference between a family being offered a time and being offered nothing. Adds email_service.describe_email_sender, the counterpart to describe_sms_sender: it walks the same organization then platform then verified-registry resolution the send performs, applies the same refusal rule send_email_via_provider applies, never raises and never returns the provider key - so what the page reports and what the send does cannot disagree. compose context now computes email availability from both halves and names which one is missing, and publishes the resolved sender. The composer states the From address and where replies will go while the advisor is writing, shows the reason when it cannot send, and disables Send rather than inviting a failure.'
& "$PSScriptRoot\deploy.ps1" -Message $msg
Write-Output ("DEPLOY_EXIT=" + $LASTEXITCODE)
